import { build } from 'esbuild'
import { join } from 'node:path'

export const HOOK_BUNDLE_NAME = 'rushdb-hooks.mjs'
/** The Claude directory takes files up to 256 KiB. */
export const HOOK_BUNDLE_LIMIT = 256 * 1024

const BANNER = [
  '// rushdb-hooks.mjs: RushDB automatic-context hooks.',
  '// GENERATED by scripts/build.ts from packages/hooks and packages/core; do not edit. Source:',
  '// https://github.com/rush-db/agent-plugins (Apache-2.0).',
  // Lets bundled CommonJS code call require() on Node built-ins from an ES module.
  "import { createRequire as __rushdbCreateRequire } from 'node:module';",
  'const require = __rushdbCreateRequire(import.meta.url);'
].join('\n')

/**
 * Bundles the hook CLI into one readable ES module: not minified, no package.json or lockfile needed next to it.
 * Paths in its comments are relative to `root`, so the output is the same on every machine with the same lockfile.
 * Throws when the bundle is over 256 KiB.
 */
export async function bundleHooks(root: string): Promise<string> {
  const result = await build({
    absWorkingDir: root,
    entryPoints: [join(root, 'packages/hooks/src/entry.ts')],
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node18',
    minify: false,
    sourcemap: false,
    legalComments: 'inline',
    charset: 'utf8',
    banner: { js: BANNER },
    write: false,
    logLevel: 'silent'
  })
  const output = result.outputFiles[0]
  if (!output) throw new Error('esbuild wrote no hook bundle')
  const size = output.contents.byteLength
  if (size > HOOK_BUNDLE_LIMIT) {
    throw new Error(
      `${HOOK_BUNDLE_NAME} is ${(size / 1024).toFixed(1)} KiB, over the ${HOOK_BUNDLE_LIMIT / 1024} KiB limit; switch the hooks to a thin fetch client`
    )
  }
  return output.text
}
